# -*- coding: utf-8 -*-
"""无条件清理悬空 junction（os.path.exists 对悬空链接返回 False，必须直接 rmdir）。"""
import os, sys
sys.stdout.reconfigure(encoding="utf-8", errors="replace")
targets = [r"E:\zhixiaoban_prj\_提交_github\openvela\.repo\manifests\.git"]
for t in targets:
    try:
        st = os.lstat(t)
        print("发现链接/目录:", t, "mode=%o" % st.st_mode)
    except FileNotFoundError:
        print("不存在:", t); continue
    except Exception as e:
        print("lstat 异常:", e); continue
    try:
        os.rmdir(t)
        print("  已用 os.rmdir 安全移除（只删链接，不动目标）")
    except Exception as e:
        print("  rmdir 失败:", e)
