ENDBAR = " " + "*" * 76 + "/"        # 78 字符
IS_BANNER = re.compile(r"^/\*{4,}\s*$")

def wrap(prefix, text, width=MAX):
    words = text.split()
    if not words: return []
    out, cur = [], ""
    for w in words:
        cand = (cur + " " + w) if cur else w
        if len(prefix) + len(cand) <= width: cur = cand
        else:
            if cur: out.append(prefix + cur)
            cur = w
    if cur: out.append(prefix + cur)
    return out

def normalize_block(indent, text_lines):
    """把注释块正文按段落重排"""
    paras, cur = [], []
    for seg in text_lines:
        s = seg.strip()
        s = s.lstrip("*").strip() if s.startswith("*") else s
        if s == "":
            if cur: paras.append(" ".join(cur)); cur = []
            paras.append("")
        elif s.startswith("-") or s.startswith("*") or re.match(r"^\d+\)", s) or s.startswith("["):
            if cur: paras.append(" ".join(cur)); cur = []
            paras.append(s)
        else:
            cur.append(s)
    if cur: paras.append(" ".join(cur))
    out = [indent + "/*"]
    for p in paras:
        if p == "": out.append(indent + " *")
        else: out.extend(wrap(indent + " * ", p))
    out.append(indent + " */")
    return out

def reflow(lines):
    out, i, n = [], 0, len(lines)
    while i < n:
        line = lines[i]; s = line.strip()
        if IS_BANNER.match(s):                      # 文件横幅：整块原样保留
            out.append(line); i += 1
            while i < n and not lines[i].strip().endswith("*/"):
                out.append(lines[i]); i += 1
            if i < n: out.append(lines[i]); i += 1
            continue
        if s.startswith("/*") and "*/" in s and s.count("/*") == 1:
            indent = line[:len(line) - len(line.lstrip())]
            text = s[2:s.rindex("*/")].strip()
            tail = s[s.rindex("*/") + 2:].strip()
            if len(line) <= MAX and not tail:
                out.append(line); i += 1; continue
            if not text:
