            if j < n:
                body.append(lines[j][:lines[j].rindex("*/")])
            out.extend(normalize_block(indent, body))
            i = j + 1; continue
        if "/*" in line and line.rstrip().endswith("*/") and len(line) > MAX:
            code, _, rest = line.partition("/*")
            comment = rest[:rest.rindex("*/")].strip()
            if code.strip():
                indent = line[:len(line) - len(line.lstrip())]
                out.extend(normalize_block(indent, [comment]))
                out.append(code.rstrip())
