# -*- coding: utf-8 -*-
"""nxfix.py - reformat C comments so openvela nxstyle (the CI checker) passes.

Only formatting is touched:
  * block comments are re-wrapped to <= 77 bytes per line
  * continuation lines get the standard ' * ' decoration
  * a multi-line comment's terminator gets a line of its own
  * own-line comments get a blank line after them
  * 'Included Files' / 'Pre-processor Definitions' section banners are added

Usage:  python nxfix.py <root> <relpath> [...]
"""
import io
import os
import re
import sys

sys.stdout.reconfigure(encoding="utf-8", errors="replace")

WIDTH = 77
BOPEN = "/" + "*" * 76
BCLOSE = " " + "*" * 76 + "/"

LIST_RE = re.compile(r"^([-*]\s|\d+[.)]\s|[\u2460-\u2473]|\([a-z]\)\s)")


def blen(s):
    return len(s.encode("utf-8"))


def wrap(prefix, text, width=WIDTH):
    words = text.split()
    if not words:
        return []
    out = []
    cur = ""
    for w in words:
        cand = w if not cur else cur + " " + w
        if blen(prefix + cand) <= width:
            cur = cand
        else:
            if cur:
                out.append(prefix + cur)
            cur = w
    if cur:
        out.append(prefix + cur)
    return out


def unstar(line):
    s = line.strip()
    if s.startswith("*") and not s.startswith("**"):
        s = s[1:]
        if s.startswith(" "):
            s = s[1:]
        s = s.rstrip()
    return s


def format_normal(indent, raw):
    pad = " " * indent
    paras = []
    cur = []
    for rl in raw:
        t = rl.strip()
        if t == "":
            if cur:
                paras.append(("t", " ".join(cur)))
                cur = []
            paras.append(("b", ""))
        elif LIST_RE.match(t):
            if cur:
                paras.append(("t", " ".join(cur)))
                cur = []
            paras.append(("i", t))
        else:
            cur.append(t)
    if cur:
        paras.append(("t", " ".join(cur)))
    while paras and paras[0][0] == "b":
        paras.pop(0)
    while paras and paras[-1][0] == "b":
        paras.pop()
    if not paras:
        return []
    if len(paras) == 1 and paras[0][0] == "t":
        line = pad + "/* " + paras[0][1] + " */"
        if blen(line) <= WIDTH:
            return [line]
    out = []
    for idx, (kind, text) in enumerate(paras):
        if kind == "b":
            out.append(pad + " *")
            continue
        prefix = pad + ("/* " if idx == 0 else " * ")
        out.extend(wrap(prefix, text))
    out.append(pad + " */")
    return out


def format_section(title):
    return [BOPEN, " * " + title, BCLOSE]


def format_banner(indent, raw):
    out = [" " * indent + BOPEN]
    for rl in raw:
        t = rl.strip()
        if t == "":
            out.append(" " * indent + " *")
        else:
            out.extend(wrap(" " * indent + " * ", t))
    out.append(" " * indent + BCLOSE)
    return out


def scan_comments(text):
    res = []
    i = 0
    n = len(text)
    while i < n:
        c = text[i]
        if c in "'" + '"':
            q = c
            i += 1
            while i < n and text[i] != q:
                if text[i] == "\\":
                    i += 1
                i += 1
            i += 1
            continue
        if c == "/" and i + 1 < n and text[i + 1] == "*":
            j = text.find("*/", i + 2)
            end = (j + 2) if j >= 0 else n
            ls = text.rfind("\n", 0, i) + 1
            le = text.find("\n", end - 1)
            if le < 0:
                le = n
            before = text[ls:i]
            after = text[end:le]
            res.append({"start": i, "end": end, "ls": ls, "le": le,
                        "before": before, "after": after,
                        "own": before.strip() == "", "raw": text[i:end]})
            i = end
            continue
        i += 1
    return res


def content_lines(raw, banner):
    body = raw[2:]
    if body.endswith("*/"):
        body = body[:-2]
    if banner:
        body = re.sub(r"^\*+", "", body, count=1)
    parts = body.split("\n")
    out = []
    for idx, p in enumerate(parts):
        if idx == 0:
            out.append(p.strip())
        else:
            out.append(unstar(p))
    return out


def is_banner(raw):
    first = raw.split("\n", 1)[0]
    return re.match(r"^\s*/\*{2,}\s*$", first) is not None


def reflow(text):
    lines = text.split("\n")
    starts = []
    off = 0
    for ln in lines:
        starts.append(off)
        off += len(ln) + 1

    def line_of(pos):
        lo, hi = 0, len(starts) - 1
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if starts[mid] <= pos:
                lo = mid
            else:
                hi = mid - 1
        return lo

    for c in reversed(scan_comments(text)):
        l0 = line_of(c["start"])
        l1 = line_of(c["end"] - 1)
        before = c["before"]
        indent = len(before) - len(before.lstrip(" \t"))
        banner = is_banner(c["raw"]) and indent == 0
        content = content_lines(c["raw"], is_banner(c["raw"]))
        if banner:
            new = format_banner(0, content)
        else:
            new = format_normal(indent, content)
        code_before = before.rstrip()
        code_after = c["after"].strip()
        if c["own"] and not code_after:
            repl = new
        elif code_before and not code_after:
            flat = re.sub(r"\s+", " ", c["raw"]).strip()
            one = code_before + " " + flat
            if "\n" not in c["raw"] and blen(one) <= WIDTH:
                repl = [one]
            else:
                repl = new + [code_before]
        else:
            continue
        if not new and not repl:
            continue
        lines[l0:l1 + 1] = repl
    return "\n".join(lines)


def strip_comments(text):
    out = []
    i = 0
    n = len(text)
    while i < n:
        c = text[i]
        if c in "'" + '"':
            q = c
            out.append(c)
            i += 1
            while i < n and text[i] != q:
                out.append(text[i])
                if text[i] == "\\":
                    i += 1
                    if i < n:
                        out.append(text[i])
                i += 1
            if i < n:
                out.append(text[i])
            i += 1
            continue
        if c == "/" and i + 1 < n and text[i + 1] == "*":
            j = text.find("*/", i + 2)
            i = (j + 2) if j >= 0 else n
            out.append(" ")
            continue
        out.append(c)
        i += 1
    return "".join(out)


def code_signature(text):
    return " ".join(strip_comments(text).split())


def add_section_banners(lines):
    joined = "\n".join(lines)
    out = list(lines)
    if "#include" in joined and " * Included Files" not in joined:
        idx = next((i for i, l in enumerate(out) if l.lstrip().startswith("#include")), None)
        if idx is not None:
            block = format_section("Included Files") + [""]
            if idx > 0 and out[idx - 1].strip() != "":
                block = [""] + block
            out[idx:idx] = block
    joined = "\n".join(out)
    if re.search(r"^[ \t]*#(define|undef)\b", joined, re.M) and " * Pre-processor Definitions" not in joined:
        idx = next((i for i, l in enumerate(out) if re.match(r"^[ \t]*#(define|undef)\b", l)), None)
        if idx is not None:
            block = format_section("Pre-processor Definitions") + [""]
            if idx > 0 and out[idx - 1].strip() != "":
                block = [""] + block
            out[idx:idx] = block
    return out


def blank_after_comments(lines):
    out = list(lines)
    i = 0
    n = len(out)
    while i < n:
        if out[i].lstrip().startswith("/*"):
            j = i
            while j < n and "*/" not in out[j]:
                j += 1
            if j >= n:
                break
            has_code_after = out[j].split("*/", 1)[1].strip() != ""
            own = out[i].strip().startswith("/*")
            if own and not has_code_after and j + 1 < n:
                nxt = out[j + 1].lstrip()
                if nxt != "" and not nxt.startswith(("}", "#")):
                    out.insert(j + 1, "")
                    n += 1
            i = j + 1
            continue
        i += 1
    return out


def process(path):
    with io.open(path, encoding="utf-8", errors="replace") as f:
        orig = f.read()
    orig = orig.replace("\r\n", "\n")
    if not orig.endswith("\n"):
        orig += "\n"
    sig0 = code_signature(orig)
    text = reflow(orig)
    lines = text.split("\n")
    if path.endswith((".c", ".h")):
        lines = add_section_banners(lines)
        lines = blank_after_comments(lines)
    lines = [l.rstrip() for l in lines]
    new = "\n".join(lines)
    sig1 = code_signature(new)
    ok = sig0 == sig1
    with io.open(path, "w", encoding="utf-8", newline="") as f:
        f.write(new)
    return ok


if __name__ == "__main__":
    root = sys.argv[1]
    bad = 0
    for rel in sys.argv[2:]:
        p = os.path.join(root, rel.replace("/", os.sep))
        ok = process(p)
        print("%-16s %s" % ("OK" if ok else "CODE-CHANGED", rel))
        if not ok:
            bad += 1
    print("code-preservation failures: %d" % bad)
