import re
import sys

sys.stdout.reconfigure(encoding="utf-8", errors="replace")

WIDTH = 77
BOPEN = "/" + "*" * 76
BCLOSE = " " + "*" * 76 + "/"

LIST_RE = re.compile(r"^([-*]\s|\d+[.)]\s|[\u2460-\u2473]|\([a-z]\)\s)")
DECOR_RE = re.compile(r"^[=\-*_~#\u2500-\u257f\u2580-\u259f\u2550-\u256c]+$")


def blen(s):
    return len(s.encode("utf-8"))


def wrap(prefix, text, width=WIDTH):
    words = text.split()
    if not words:
        return []
    out = []
    cur = ""
    for w in words:
        cand = w if not cur else cur + " " + w
        if blen(prefix + cand) <= width:
            cur = cand
        else:
            if cur:
                out.append(prefix + cur)
            cur = w
    if cur:
        out.append(prefix + cur)
    return out


def wrap_first(first_prefix, rest_prefix, text, width=WIDTH):
    words = text.split()
    if not words:
        return []
    out = []
    cur = ""
    prefix = first_prefix
    for w in words:
        cand = w if not cur else cur + " " + w
        if blen(prefix + cand) <= width:
            cur = cand
            continue
        if cur:
            out.append(prefix + cur)
            prefix = rest_prefix
            cur = w
        else:
            out.append(prefix + w)
            prefix = rest_prefix
            cur = ""
    if cur:
        out.append(prefix + cur)
    return out


def unstar(line):
    s = line.strip()
    if s.startswith("*") and not s.startswith("**"):
        s = s[1:]
        if s.startswith(" "):
            s = s[1:]
        s = s.rstrip()
    return s


def format_normal(indent, raw):
    pad = " " * indent
    paras = []
    cur = []
    for rl in raw:
        t = rl.strip()
        if t == "":
            if cur:
                paras.append(("t", " ".join(cur)))
                cur = []
            paras.append(("b", ""))
        elif LIST_RE.match(t):
            if cur:
                paras.append(("t", " ".join(cur)))
                cur = []
            paras.append(("i", t))
        else:
            cur.append(t)
    if cur:
        paras.append(("t", " ".join(cur)))
    while paras and paras[0][0] == "b":
        paras.pop(0)
    while paras and paras[-1][0] == "b":
        paras.pop()
    if not paras:
        return []
    if len(paras) == 1 and paras[0][0] == "t":
        line = pad + "/* " + paras[0][1] + " */"
        if blen(line) <= WIDTH:
            return [line]
    out = []
    for idx, (kind, text) in enumerate(paras):
        if kind == "b":
            out.append(pad + " *")
            continue
        if idx == 0:
            out.extend(wrap_first(pad + "/* ", pad + " * ", text))
        else:
            out.extend(wrap(pad + " * ", text))
    out.append(pad + " */")
    return out


def format_section(title):
    return [BOPEN, " * " + title, BCLOSE]


def format_banner(indent, raw):
    while raw and raw[0].strip() == "":
        raw = raw[1:]
    while raw and raw[-1].strip() == "":
        raw = raw[:-1]
    out = [" " * indent + BOPEN]
    for rl in raw:
        t = rl.strip()
        if t == "":
            out.append(" " * indent + " *")
        else:
            out.extend(wrap(" " * indent + " * ", t))
    out.append(" " * indent + BCLOSE)
    return out


def scan_comments(text):
    res = []
    i = 0
    n = len(text)
    while i < n:
        c = text[i]
        if c in "'" + '"':
            q = c
            i += 1
            while i < n and text[i] != q:
                if text[i] == "\\":
                    i += 1
                i += 1
            i += 1
            continue
        if c == "/" and i + 1 < n and text[i + 1] == "*":
            j = text.find("*/", i + 2)
            end = (j + 2) if j >= 0 else n
            ls = text.rfind("\n", 0, i) + 1
            le = text.find("\n", end - 1)
            if le < 0:
                le = n
            before = text[ls:i]
            res.append({"start": i, "end": end, "ls": ls, "le": le,
                        "before": before, "after": text[end:le],
                        "own": before.strip() == "", "raw": text[i:end]})
            i = end
            continue
        i += 1
    return res


def content_lines(raw, banner):
    body = raw[2:]
    if body.endswith("*/"):
        body = body[:-2]
    parts = body.split("\n")
    if banner:
        parts[0] = re.sub(r"^\s*\*+", "", parts[0], count=1)
        if re.match(r"^\s*\*+\s*$", parts[-1]):
            parts[-1] = ""
    out = []
    for idx, p in enumerate(parts):
        if idx == 0:
            out.append(p.strip())
        else:
            out.append(unstar(p))
    return out


def is_banner(raw):
    return re.match(r"^\s*/\*{2,}\s*$", raw.split("\n", 1)[0]) is not None


def comment_is_ok(lines, indent):
    if indent != 0 and indent % 4 != 2:
        return False
    if any(blen(l) > WIDTH for l in lines):
        if not (any(l.rstrip().endswith("*/") for l in lines[1:])):
            return False
    if is_banner("\n".join(lines)):
        if lines[0] != BOPEN or lines[-1] != BCLOSE:
            return False
        for l in lines[1:-1]:
            if l != " *" and not l.startswith(" * "):
                return False
        return True
    if len(lines) == 1:
        l = lines[0]
        return l.strip().startswith("/* ") and l.rstrip().endswith(" */")
    if not lines[0].strip().startswith("/* "):
        return False
    if lines[-1] != " " * indent + " */":
        return False
    for l in lines[1:-1]:
        if l != " " * indent + " *" and not l.startswith(" " * indent + " * "):
            return False
    return True


def reflow(text):
    lines = text.split("\n")
    starts = []
    off = 0
    for ln in lines:
        starts.append(off)
        off += len(ln) + 1

    def line_of(pos):
        lo, hi = 0, len(starts) - 1
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if starts[mid] <= pos:
                lo = mid
            else:
                hi = mid - 1
        return lo

    for c in reversed(scan_comments(text)):
        l0 = line_of(c["start"])
        l1 = line_of(c["end"] - 1)
        before = c["before"]
        indent = len(before) - len(before.lstrip(" \t"))
        if indent == 1:
            indent = 0
        elif indent == 3:
            indent = 2
        raw_lines = lines[l0:l1 + 1]
        banner = is_banner(c["raw"]) and indent == 0
        code_after = c["after"].strip()
        code_before = before.rstrip()
        if c["own"] and not code_after:
            if comment_is_ok(raw_lines, indent):
                continue
            content = [x for x in content_lines(c["raw"], is_banner(c["raw"]))
                       if not DECOR_RE.match(x)]
            new = format_banner(0, content) if banner else format_normal(indent, content)
            if not new:
                new = []
            lines[l0:l1 + 1] = new
        elif code_before and not code_after:
            if "\n" not in c["raw"] and blen(lines[l0]) <= WIDTH:
                continue
            content = [x for x in content_lines(c["raw"], False)
                       if not DECOR_RE.match(x)]
            new = format_normal(indent, content)
            lines[l0:l1 + 1] = new + [code_before]
    return "\n".join(lines)


def strip_comments(text):
    out = []
    i = 0
    n = len(text)
    while i < n:
        c = text[i]
        if c in "'" + '"':
            q = c
            out.append(c)
            i += 1
            while i < n and text[i] != q:
                out.append(text[i])
                if text[i] == "\\":
                    i += 1
                    if i < n:
                        out.append(text[i])
                i += 1
            if i < n:
                out.append(text[i])
            i += 1
            continue
        if c == "/" and i + 1 < n and text[i + 1] == "*":
            j = text.find("*/", i + 2)
            i = (j + 2) if j >= 0 else n
            out.append(" ")
            continue
        out.append(c)
        i += 1
    return "".join(out)


def code_signature(text):
    return " ".join(strip_comments(text).split())


def fix_header_path(text, relpath):
    lines = text.split("\n")
    if len(lines) < 3 or not lines[0].startswith("/********"):
        return text
    m = re.match(r"^ \* (.*\S)\s*$", lines[1])
    if not m:
        return text
    cur = m.group(1)
    if cur == relpath:
        return text
    if re.match(r"^[\w./-]+\.(c|h)$", cur):
        lines[1] = " * " + relpath
        return "\n".join(lines)
    desc = re.sub(r"^[\w./-]+\.(c|h)\s*[\u2014\u2013-]\s*", "", cur)
    lines[1] = " * " + relpath
    if desc.strip():
        lines[2:2] = [" *", " * " + desc]
    return "\n".join(lines)


def add_section_banners(lines):
    joined = "\n".join(lines)
    out = list(lines)
    if "#include" in joined and " * Included Files" not in joined:
        idx = next((i for i, l in enumerate(out) if l.lstrip().startswith("#include")), None)
        if idx is not None:
            block = format_section("Included Files") + [""]
            if idx > 0 and out[idx - 1].strip() != "":
                block = [""] + block
            out[idx:idx] = block
    joined = "\n".join(out)
    if re.search(r"^[ \t]*#(define|undef)\b", joined, re.M) and " * Pre-processor Definitions" not in joined:
        idx = None
        for i, l in enumerate(out):
            if re.match(r"^[ \t]*#(define|undef)\b", l):
                prev = out[i - 1].strip() if i > 0 else ""
                if prev.startswith("#ifndef"):
                    continue
                idx = i
                break
        if idx is not None:
            block = format_section("Pre-processor Definitions") + [""]
            if idx > 0 and out[idx - 1].strip() != "":
                block = [""] + block
            out[idx:idx] = block
    return out


def blank_lines(lines):
    out = list(lines)
    i = 0
    n = len(out)
    while i < n:
        if out[i].lstrip().startswith("/*"):
            j = i
            while j < n and "*/" not in out[j]:
                j += 1
            if j >= n:
                break
            tail = out[j].split("*/", 1)[1].strip()
            own = out[i].strip().startswith("/*")
            single = (i == j)
            if own and tail == "" and j + 1 < n:
                nxt = out[j + 1].lstrip()
                if nxt != "" and not nxt.startswith(("}", "#")):
                    out.insert(j + 1, "")
                    n += 1
            if own and single and i > 0:
                prev = out[i - 1]
                pv = prev.rstrip()
                if prev.strip() != "" and not pv.endswith("{") and not prev.lstrip().startswith("#"):
                    if not pv.endswith("*/"):
                        out.insert(i, "")
                        n += 1
                        i += 1
            i = j + 2
            continue
        i += 1
    return out


def process(root, rel):
    path = os.path.join(root, rel.replace("/", os.sep))
    with io.open(path, encoding="utf-8", errors="replace") as f:
        orig = f.read()
    orig = orig.replace("\r\n", "\n")
    if not orig.endswith("\n"):
        orig += "\n"
    sig0 = code_signature(orig)
    text = orig
    if rel.endswith((".c", ".h")):
        text = fix_header_path(text, rel)
    text = reflow(text)
    lines = text.split("\n")
    if rel.endswith((".c", ".h")):
        lines = add_section_banners(lines)
        lines = blank_lines(lines)
    lines = [l.rstrip() for l in lines]
    new = "\n".join(lines)
    ok = code_signature(new) == sig0
    with io.open(path, "w", encoding="utf-8", newline="") as f:
        f.write(new)
    return ok


if __name__ == "__main__":
    root = sys.argv[1]
    bad = 0
    for rel in sys.argv[2:]:
        ok = process(root, rel)
        print("%-16s %s" % ("OK" if ok else "CODE-CHANGED", rel))
        if not ok:
            bad += 1
    print("code-preservation failures: %d" % bad)
