```python
def shift_range(text, first, last, delta):
    """first/last are 1-based line numbers"""
    lines = text.split("\n")
    for i in range(first-1, last):
        if lines[i].strip():
            if delta > 0:
                lines[i] = " " * delta + lines[i]
            else:
                n = min(-delta, len(lines[i]) - len(lines[i].lstrip(" ")))
                lines[i] = lines[i][n:]
    return "\n".join(lines)
```
