# -*- coding: utf-8 -*-
"""mk_logs.py - export this product's Codex sessions into the contest log schema.

Codex (desktop/CLI) writes rollouts as {timestamp, ordinal, type, payload}.
The official collector's shipped Codex path only understands Claude-Code-shaped
transcripts, so the payload has to be flattened first (this is the same
adaptation described in the team's report to the organisers).

Content rules follow the organisers' own Codex adapter (PR #52):
  * only role user / assistant are kept (tool preamble blobs are dropped)
  * environment boilerplate prefixes are dropped
  * additionally we keep reasoning (-> thinking) and tool calls/results, which
    the schema and the Claude Code collector path both record.

Usage:  python mk_logs.py --measure | --write
"""
import hashlib
import io
import json
import os
import sys
from datetime import datetime, timezone
from pathlib import Path

