TEAM_ID = "contest2026_053_yelvtizhineng"
LOGIN = "tadycharming"
TOOL = "codex"
SCHEMA = "1.0"

PROJECT_CWD_MARK = "植小伴"
BOILERPLATE = ("<permissions instructions>", "<skills_instructions>",
               "<environment_context>", "<app-context>")
CATEGORIES = ("text", "thinking", "tool_call", "tool_result")


def codex_home() -> Path:
    return Path(os.environ.get("CODEX_HOME") or (Path.home() / ".codex"))


def content_text(payload: dict) -> str:
    parts = []
    for b in payload.get("content") or []:
        if not isinstance(b, dict):
            continue
        bt = b.get("type")
        if bt in ("input_text", "output_text", "text"):
            t = b.get("text")
            if isinstance(t, str) and t.strip():
                parts.append(t)
        elif bt in ("input_image", "image"):
            parts.append("[image]")
    return "\n".join(parts)


def expand(rec: dict):
    """one rollout line -> list of (category, event-dict)"""
    out = []
    ts = rec.get("timestamp") or ""
    if rec.get("type") != "response_item":
        return out
    p = rec.get("payload") or {}
    pt = p.get("type")
    if pt == "message":
        role = (p.get("role") or "assistant").lower()
        if role not in ("user", "assistant"):
            return out
        text = content_text(p)
        if not text or any(text.startswith(x) for x in BOILERPLATE):
            return out
        out.append(("text", {"ts": ts, "role": role, "text": text}))
    elif pt == "reasoning":
        txt = "".join(str(x.get("text", "")) for x in (p.get("summary") or [])
                      if isinstance(x, dict))
        if txt:
            out.append(("thinking", {"ts": ts, "role": "assistant", "thinking": txt}))
    elif pt == "function_call":
        out.append(("tool_call", {"ts": ts, "role": "tool",
                                  "tool_name": p.get("name", "unknown"),
                                  "tool_call_id": p.get("call_id", ""),
                                  "input": p.get("arguments"), "output": None}))
    elif pt == "function_call_output":
        out.append(("tool_result", {"ts": ts, "role": "tool", "tool_name": "<result>",
                                    "tool_call_id": p.get("call_id", ""),
                                    "input": None, "output": p.get("output")}))
    return out


def scan(include_tools: bool, include_thinking: bool, write: bool):
    home = codex_home()
    roots = [home / "sessions", home / "archived_sessions"]
    rollouts = sorted({p for r in roots if r.is_dir() for p in r.rglob("rollout-*.jsonl")})
    base = Path(r"E:\zhixiaoban_prj\_提交_github\openvela\contest2026_053_yelvtizhineng")
    dest_member = base / "logs" / LOGIN

