                    try:
                        rec = json.loads(line)
                    except json.JSONDecodeError:
                        continue
                    if rec.get("type") == "session_meta" and meta is None:
                        meta = rec.get("payload") or {}
                    recs.append(rec)
        except OSError:
            continue
        if not meta or PROJECT_CWD_MARK not in str(meta.get("cwd", "")):
            continue
        sid = meta.get("session_id") or p.stem
        model = None
        evs = []
        for rec in recs:
            if rec.get("type") == "turn_context":
                model = (rec.get("payload") or {}).get("model") or model
            for cat, ev in expand(rec):
