# -*- coding: utf-8 -*-
"""Generate this product's AI coding logs from the real Codex transcripts.

Content rules follow the organisers' own Codex adapter (open-vela/.claude PR #52):
only role user/assistant dialogue is kept, tool preamble blobs are dropped.
We additionally keep reasoning (thinking) and tool calls/results, which the
event schema and the Claude Code collector path both record.
"""
import hashlib
import io
import json
import os
import sys
from datetime import datetime, timezone
from pathlib import Path

sys.stdout.reconfigure(encoding="utf-8", errors="replace")

TEAM_ID = "contest2026_053_yelvtizhineng"
LOGIN = "tadycharming"
TOOL = "codex"
SCHEMA = "1.0"
PROJECT_CWD_MARK = "植小伴"
BOILERPLATE = ("<permissions instructions>", "<skills_instructions>",
               "<environment_context>", "<app-context>")
BASE = Path(r"E:\zhixiaoban_prj\_提交_github\openvela\contest2026_053_yelvtizhineng")


def codex_home():
    return Path(os.environ.get("CODEX_HOME") or (Path.home() / ".codex"))


def content_text(payload):
    parts = []
    for b in payload.get("content") or []:
        if not isinstance(b, dict):
            continue
        bt = b.get("type")
        if bt in ("input_text", "output_text", "text"):
            t = b.get("text")
            if isinstance(t, str) and t.strip():
                parts.append(t)
        elif bt in ("input_image", "image"):
            parts.append("[image]")
    return "\n".join(parts)


def expand(rec):
    out = []
    ts = rec.get("timestamp") or ""
    if rec.get("type") != "response_item":
        return out
    p = rec.get("payload") or {}
    pt = p.get("type")
    if pt == "message":
        role = (p.get("role") or "assistant").lower()
        if role not in ("user", "assistant"):
            return out
        text = content_text(p)
        if not text or any(text.startswith(x) for x in BOILERPLATE):
            return out
        out.append({"ts": ts, "role": role, "text": text})
    elif pt == "reasoning":
        txt = "".join(str(x.get("text", "")) for x in (p.get("summary") or [])
                      if isinstance(x, dict))
        if txt:
            out.append({"ts": ts, "role": "assistant", "thinking": txt})
    elif pt == "function_call":
        out.append({"ts": ts, "role": "tool",
                    "tool_name": p.get("name", "unknown"),
                    "tool_call_id": p.get("call_id", ""),
                    "input": p.get("arguments"), "output": None})
    elif pt == "function_call_output":
        out.append({"ts": ts, "role": "tool", "tool_name": "<result>",
                    "tool_call_id": p.get("call_id", ""),
                    "input": None, "output": p.get("output")})
    return out


def sha256_file(p):
    h = hashlib.sha256()
    with p.open("rb") as f:
        for chunk in iter(lambda: f.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()


def main():
    home = codex_home()
    rollouts = sorted({p for r in [home / "sessions", home / "archived_sessions"]
                       if r.is_dir() for p in r.rglob("rollout-*.jsonl")})
    sessions = {}
    for p in rollouts:
        meta = None
        model = None
        evs = []
        last_ts = ""
        with p.open(encoding="utf-8", errors="replace") as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                try:
                    rec = json.loads(line)
                except json.JSONDecodeError:
                    continue
                if rec.get("type") == "session_meta" and meta is None:
                    meta = rec.get("payload") or {}
                if rec.get("type") == "turn_context":
                    model = (rec.get("payload") or {}).get("model") or model
                for ev in expand(rec):
                    if not ev["ts"]:
                        ev["ts"] = last_ts
                    if not ev["ts"]:
                        continue
                    last_ts = ev["ts"]
                    if model and ev["role"] == "assistant":
                        ev["model"] = model
                    evs.append(ev)
        if not meta or PROJECT_CWD_MARK not in str(meta.get("cwd", "")) or not evs:
            continue
        sid = meta.get("session_id") or p.stem
        d = sessions.setdefault(sid, {"files": [], "events": [], "model": model})
        d["files"].append(p)
        d["events"].extend(evs)
        if model:
            d["model"] = model

    member = BASE / "logs" / LOGIN
    manifest_sessions = []
    written = []
    for sid, d in sessions.items():
        evs = d["events"]
        date = evs[0]["ts"][:10]
        rel = "logs/%s/%s/%s__%s.jsonl" % (LOGIN, date, TOOL, sid)
        out = BASE / rel
        out.parent.mkdir(parents=True, exist_ok=True)
        with out.open("w", encoding="utf-8", newline="") as f:
            for seq, ev in enumerate(evs):
                rec = {"schema_version": SCHEMA, "session_id": sid, "team_id": TEAM_ID,
                       "github_login": LOGIN, "tool": TOOL, "seq": seq, **ev}
                f.write(json.dumps(rec, ensure_ascii=False) + "\n")
        size = out.stat().st_size
        written.append((sid, len(evs), size))
        manifest_sessions.append({
            "session_id": sid,
            "tool": TOOL,
            "started_at": evs[0]["ts"],
            "last_event_at": evs[-1]["ts"],
            "event_count": len(evs),
            "file_path": rel,
            "collection_mode": "cli",
            "health": "ok",
            **({"model": d["model"]} if d["model"] else {}),
            "source_integrity": {
                "captured_at": datetime.now(timezone.utc).isoformat().replace("+00:00", "Z"),
                "source_files": [{"path": str(p), "sha256": sha256_file(p),
                                  "size": p.stat().st_size} for p in d["files"]],
                "note": ("Codex rollout transcript(s); exported with a Codex-format "
                         "adapter because the shipped collector could not parse the "
                         "rollout layout - see logs/README.md")
            }
        })
        print("  wrote %6d event(s) %8.1f MB -> %s" % (len(evs), size / 1e6, rel))

    manifest = {
        "schema_version": SCHEMA,
        "team_id": TEAM_ID,
        "github_login": LOGIN,
        "generator": "codex-rollout-adapter@1.0 (local export; see logs/README.md)",
        "updated_at": datetime.now(timezone.utc).isoformat().replace("+00:00", "Z"),
        "sessions": manifest_sessions,
    }
    mp = member / "manifest.json"
    mp.write_text(json.dumps(manifest, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print("  manifest -> %s (%d sessions)" % (mp.relative_to(BASE), len(manifest_sessions)))
    print()
    print("total: %d sessions, %d events, %.1f MB" % (len(written), sum(w[1] for w in written),
                                                      sum(w[2] for w in written) / 1e6))


if __name__ == "__main__":
    main()
